import{_ as a,c as e,o as t,ag as r}from"./chunks/framework.DPDPlp3K.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"notion/NixOS社区成员成长路线.md","filePath":"notion/NixOS社区成员成长路线.md"}'),l={name:"notion/NixOS社区成员成长路线.md"};function s(n,i,o,h,p,d){return t(),e("div",null,i[0]||(i[0]=[r(`<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>手把手梳理：NixOS社区成员成长路线</li><li>NixOS社区成员成长路线 学习笔记：核心概念和实践步骤一次讲清楚</li><li>从零理解 NixOS社区成员成长路线：把容易混淆的地方说明白</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章围绕「NixOS社区成员成长路线」整理核心概念、实践步骤和注意事项，适合需要快速复习或动手验证的技术同学阅读。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群，群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源，关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>把零散笔记整理成可复用的方法，才是真的学到手。</strong></p><p>这类知识点如果只看一遍，很容易停留在“好像懂了”的阶段。</p><p>这篇围绕「NixOS社区成员成长路线」把关键概念和操作步骤重新梳理，方便后续复习和实践。</p><h2 id="正文整理" tabindex="-1">正文整理 <a class="header-anchor" href="#正文整理" aria-label="Permalink to &quot;正文整理&quot;">​</a></h2><p>下面进入正文整理。建议大家按自己的使用场景挑重点看，再回到实践里验证。</p><p>如果你也在整理自己的技术笔记，可以把本文当作一个结构参考：先讲问题，再讲步骤，最后补注意点。</p><h2 id="nixos-nixpkgs-社区成长路线-从普通用户-→-参与pr审核-→-拥有官方审核权限" tabindex="-1">NixOS/nixpkgs 社区成长路线：从普通用户 → 参与PR审核 → 拥有官方审核权限 <a class="header-anchor" href="#nixos-nixpkgs-社区成长路线-从普通用户-→-参与pr审核-→-拥有官方审核权限" aria-label="Permalink to &quot;NixOS/nixpkgs 社区成长路线：从普通用户 → 参与PR审核 → 拥有官方审核权限&quot;">​</a></h2><h2 id="一、先理清社区4个核心角色-对应审核权限" tabindex="-1">一、先理清社区4个核心角色（对应审核权限） <a class="header-anchor" href="#一、先理清社区4个核心角色-对应审核权限" aria-label="Permalink to &quot;一、先理清社区4个核心角色（对应审核权限）&quot;">​</a></h2><h3 id="_1-普通贡献者-任何人-无仓库权限" tabindex="-1">1. 普通贡献者（任何人，无仓库权限） <a class="header-anchor" href="#_1-普通贡献者-任何人-无仓库权限" aria-label="Permalink to &quot;1. 普通贡献者（任何人，无仓库权限）&quot;">​</a></h3><p><strong>无需申请，立刻就能免费参与PR评论/基础审核</strong></p><ul><li>权限：可以在任意PR下写评论、指出规范/构建问题、用<code>nixpkgs-review</code>验证构建、给出Review意见</li><li>门槛：会打包、看懂CONTRIBUTING规范、会用<code>nixpkgs-review</code>测试PR</li><li>你现在就能做，不需要任何人批准</li></ul><h3 id="_2-单包维护者-package-maintainer-你现阶段优先达成" tabindex="-1">2. 单包维护者 Package Maintainer（你现阶段优先达成） <a class="header-anchor" href="#_2-单包维护者-package-maintainer-你现阶段优先达成" aria-label="Permalink to &quot;2. 单包维护者 Package Maintainer（你现阶段优先达成）&quot;">​</a></h3><p>给某个软件包长期提交更新/修复，把自己加入<code>maintainers/maintainer-list.nix</code>，再加到对应包<code>meta.maintainers</code></p><ul><li>权限：对应包的PR会自动@你，你拥有该包<strong>优先审核权</strong>，你的approve对合并有极高权重</li><li>福利：长期负责一类包后可晋升Triager</li></ul><h3 id="_3-triager-全局pr分拣-审核者-官方轻量权限" tabindex="-1">3. Triager（全局PR分拣/审核者，官方轻量权限） <a class="header-anchor" href="#_3-triager-全局pr分拣-审核者-官方轻量权限" aria-label="Permalink to &quot;3. Triager（全局PR分拣/审核者，官方轻量权限）&quot;">​</a></h3><p>社区认可你的长期稳定审核贡献后，官方授予GitHub团队权限</p><ul><li>权限：给PR打标签、标记等待合并、分配维护者、官方Review签名、批量分拣待审核PR</li><li>核心职责：日常清理堆积PR、检查提交规范、验证构建、引导新人修正提交（拆分commit、rebase、修复noindex等）</li></ul><h3 id="_4-committer-core-maintainer-仓库写入权限-可合并pr" tabindex="-1">4. Committer / Core Maintainer（仓库写入权限，可合并PR） <a class="header-anchor" href="#_4-committer-core-maintainer-仓库写入权限-可合并pr" aria-label="Permalink to &quot;4. Committer / Core Maintainer（仓库写入权限，可合并PR）&quot;">​</a></h3><p>长期高质量Triage+子系统维护，核心团队提名投票通过</p><ul><li>权限：approve + 一键合并PR、回滚、分支推送、发布渠道管理</li></ul><hr><h2 id="二、第一步-普通人零门槛参与pr审核-现在就能动手" tabindex="-1">二、第一步：普通人零门槛参与PR审核（现在就能动手） <a class="header-anchor" href="#二、第一步-普通人零门槛参与pr审核-现在就能动手" aria-label="Permalink to &quot;二、第一步：普通人零门槛参与PR审核（现在就能动手）&quot;">​</a></h2><h3 id="_1-必备技能-你已经掌握大半" tabindex="-1">1. 必备技能（你已经掌握大半） <a class="header-anchor" href="#_1-必备技能-你已经掌握大半" aria-label="Permalink to &quot;1. 必备技能（你已经掌握大半）&quot;">​</a></h3><ol><li>熟悉nixpkgs提交规范：commit格式、单一职责拆分提交、rebase保持线性树、禁止merge提交</li><li>熟练使用 <code>nixpkgs-review pr &lt;编号&gt;</code> 跨架构构建验证PR</li><li>看懂包语法：版本更新、darwin/macOS平台支持、meta字段、extraInstallCommands、by-name目录规范</li><li>读懂维护者常见Review话术（拆分提交、rebase、补充平台、修正hash等）</li></ol><h3 id="_2-去哪里找待审核pr" tabindex="-1">2. 去哪里找待审核PR <a class="header-anchor" href="#_2-去哪里找待审核pr" aria-label="Permalink to &quot;2. 去哪里找待审核PR&quot;">​</a></h3><ol><li>GitHub筛选标签：<code>status: needs review</code><a href="https://github.com/NixOS/nixpkgs/pulls?q=is%3Aopen+is%3Apr+label%3A%22status%3A+needs+review%22" target="_blank" rel="noreferrer">https://github.com/NixOS/nixpkgs/pulls?q=is%3Aopen+is%3Apr+label%3A&quot;status%3A+needs+review&quot;</a></li><li>筛选macOS相关PR（你的优势方向）：<code>platform: darwin</code></li><li>小包更新、版本升级类PR（审核成本低，容易练手）</li></ol><h3 id="_3-标准审核操作流程-模仿官方维护者" tabindex="-1">3. 标准审核操作流程（模仿官方维护者） <a class="header-anchor" href="#_3-标准审核操作流程-模仿官方维护者" aria-label="Permalink to &quot;3. 标准审核操作流程（模仿官方维护者）&quot;">​</a></h3><ol><li>运行 <code>nixpkgs-review pr --nom --system aarch64-darwin PR号</code> 验证构建是否成功</li><li>检查提交：是否单一职责、commit消息符合规范、是否混合多类修改</li><li>检查代码：平台支持、meta属性、安装脚本、hash/版本正确性</li><li>留下规范Review： <ul><li>构建失败：贴日志，建议修复</li><li>多改动混在一条commit：要求拆分两次提交（你收到的那条英文评论模板直接复用）</li><li>历史有merge分叉：要求<code>git rebase upstream/master</code>清理树</li></ul></li><li>无问题则评论 <code>LGTM, builds fine on aarch64-darwin</code> 并点Approve</li></ol><h3 id="_4-社区沟通渠道-融入社区" tabindex="-1">4. 社区沟通渠道（融入社区） <a class="header-anchor" href="#_4-社区沟通渠道-融入社区" aria-label="Permalink to &quot;4. 社区沟通渠道（融入社区）&quot;">​</a></h3><ol><li>Discourse论坛：<a href="https://discourse.nixos.org/" target="_blank" rel="noreferrer">https://discourse.nixos.org/</a> 发帖分享打包/审核经验</li><li>Matrix/IRC社区群：#nixpkgs 实时交流维护者</li><li>积极回复新人PR提问，耐心指导git规范，积累社区口碑</li></ol><hr><h2 id="三、第二步-成为package-maintainer-拥有专属包审核权" tabindex="-1">三、第二步：成为Package Maintainer（拥有专属包审核权） <a class="header-anchor" href="#三、第二步-成为package-maintainer-拥有专属包审核权" aria-label="Permalink to &quot;三、第二步：成为Package Maintainer（拥有专属包审核权）&quot;">​</a></h2><ol><li>持续给同一个/一类软件提交PR（比如你长期维护Snipaste） <ul><li>版本升级、macOS兼容修复、完善desktop图标安装、backport稳定分支</li></ul></li><li>提交PR把自己加入全局维护者列表 文件：<code>maintainers/maintainer-list.nix</code> 格式示例：<div class="language-nix vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nix</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">{</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  github</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> =</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;kenis0225&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  githubId</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> =</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 123456</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;"> # 通过 https://api.github.com/users/kenis0225 获取id</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  name</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> =</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;kenis&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  email</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> =</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;xxx@xxx.com&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">;</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">}</span></span></code></pre></div></li><li>修改对应包<code>meta.maintainers = [ lib.maintainers.kenis ];</code> 提交合并</li><li>之后所有该包的更新PR会自动通知你，你是第一审核人</li></ol><hr><h2 id="四、第三步-申请triager全局审核权限-官方团队身份" tabindex="-1">四、第三步：申请Triager全局审核权限（官方团队身份） <a class="header-anchor" href="#四、第三步-申请triager全局审核权限-官方团队身份" aria-label="Permalink to &quot;四、第三步：申请Triager全局审核权限（官方团队身份）&quot;">​</a></h2><h3 id="申请门槛-社区通用标准" tabindex="-1">申请门槛（社区通用标准） <a class="header-anchor" href="#申请门槛-社区通用标准" aria-label="Permalink to &quot;申请门槛（社区通用标准）&quot;">​</a></h3><ol><li>持续30天以上稳定做PR分拣、Review，累计数十条有效审核记录</li><li>熟悉全量CONTRIBUTING规范，能独立引导新人修正提交历史、拆分commit、处理冲突</li><li>熟悉标签体系：<code>platform: darwin</code>、<code>status: needs rebase</code>、<code>has maintainer</code>、<code>backport</code>等</li><li>有至少1个长期维护的软件包，证明打包功底</li></ol><h3 id="申请渠道" tabindex="-1">申请渠道 <a class="header-anchor" href="#申请渠道" aria-label="Permalink to &quot;申请渠道&quot;">​</a></h3><ol><li>在Discourse开申请帖，附上你的GitHub主页+过往Review截图</li><li>现有Triager/Maintainer提名，社区简单共识后管理员添加进GitHub <code>nixpkgs-triagers</code> 团队</li><li>获得权限后可批量分拣PR、打标签、官方标记审核意见，大幅提升社区参与权重</li></ol><hr><h2 id="五、进阶-成为committer-拥有合并pr权限" tabindex="-1">五、进阶：成为Committer（拥有合并PR权限） <a class="header-anchor" href="#五、进阶-成为committer-拥有合并pr权限" aria-label="Permalink to &quot;五、进阶：成为Committer（拥有合并PR权限）&quot;">​</a></h2><ol><li>长期Triager + 子系统维护（如darwin/macOS子系统维护者）</li><li>深度参与RFC、发布流程、渠道稳定性保障</li><li>由核心Committer提名，社区投票通过，授予仓库写入权限</li></ol><hr><h2 id="六、给你的短期行动清单-1个月落地" tabindex="-1">六、给你的短期行动清单（1个月落地） <a class="header-anchor" href="#六、给你的短期行动清单-1个月落地" aria-label="Permalink to &quot;六、给你的短期行动清单（1个月落地）&quot;">​</a></h2><ol><li>持续完成自己Snipaste完整PR（拆分2条commit、rebase干净历史、过审核合并）</li><li>每天找2~3个macOS相关小包PR做完整Review，用nixpkgs-review验证并留下规范评论</li><li>提交PR将自己加入<code>maintainer-list.nix</code>，绑定snipaste为你的维护包</li><li>在Matrix/Discourse参与社区讨论，主动帮助新人解决git rebase、拆分提交问题</li><li>积累足够Review记录后发帖申请Triager权限，正式拥有官方PR审核身份</li></ol><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你还想看「NixOS社区成员成长路线」相关的哪一块展开？可以把你的使用场景或具体问题留言给我。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>技术笔记</p>`,63)]))}const m=a(l,[["render",s]]);export{k as __pageData,m as default};
